mapper.select:
           select  a.bookset_id booksetId,a.bookset_name booksetName from BOK_BOOKSET a where 1=1

           		and a.bookSet_Type=#{bookSetType}  


        		AND (
        			bookset_id like '%' || #{search,jdbcType=VARCHAR} || '%' or bookset_name like '%' || #{search,jdbcType=VARCHAR} || '%'
        		)


	        	AND  vb.BOOKSET_ID in

	         		#{item}




	            and a.ACCT_SUBJECT_TYPE != #{acctSubjectTypeNo}

select a.bookset_id id, a.bookset_name text from BOK_BOOKSET a where 1=1
AND (a.bookset_id like concat('%',concat(#{search},'%')) OR a.bookset_name like concat('%',concat(#{search},'%')))
and a.bookSet_Type=#{bookSetType}
and a.ACCT_SUBJECT_TYPE != #{acctSubjectTypeNo}

SELECT vb.bookset_id as booksetId, to_char(vb.bookset_date,'YYYY-MM-DD') as booksetDate, bb.BOOKSET_NAME as booksetName, to_char(bb.START_DATE,'YYYY-MM-DD') as startDate, to_char(bb.END_DATE,'YYYY-MM-DD') as endDate FROM BOK_BOOKSET_DATE vb LEFT JOIN BOK_BOOKSET bb ON bb.BOOKSET_ID = vb.BOOKSET_ID WHERE bb.BOOKSET_TYPE = #{booksetType}
AND vb.BOOKSET_ID in
#{item}

   select  a.bookset_id id,a.bookset_name text from BOK_BOOKSET a where 1=1

   		and a.bookSet_Type=#{booksetType}  


	AND	(a.bookset_id like concat('%',concat(#{search},'%'))
		OR a.bookset_name like concat('%',concat(#{search},'%')))


   		and a.acct_subject_type != #{acctSubjectTypeNo}

     	select distinct a.bookset_date from bok_bookset_date a where 1=1

	            AND a.bookset_Id in

		                #{booksetId}



	            AND a.bookset_Id in

		                #{item}

select count(*) from sys_batchgrp_exec_info info left join SYS_BATCH_GRP_PRDLINK grplink on info.prd_group_seq_no=grplink.group_seq where 1=1 and info.status in('UNR','RUN')
AND grplink.product_id in
#{booksetId}

select tc.happenDate, tc.booksetDate, tc.bookDate, tc.booksetId, tc.bokDetailId, tc.invAim from ( SELECT TL.HAPPEN_DATE as happenDate,--发生日期 TL.BOOKSET_DATE as booksetDate,--账套日期 TL.BOOK_DATE as bookDate,--入账日期 TL.BOOKSET_ID as booksetId, --账套代码 TL.BUSI_ID as bokDetailId,--业务明细代码 case when(JY.INV_AIM IS NOT NULL AND JY.C_INV_AIM IN('FVTPL','FVOCI')) then JY.C_INV_AIM ELSE TL.INV_AIM END AS invAim FROM ( select temp.HAPPEN_DATE, temp.BOOKSET_DATE, temp.BOOK_DATE, temp.BOOKSET_ID, temp.BUSI_ID, temp.INV_AIM, temp.FINPROD_TYPE from ( select bp.*, row_number() over ( PARTITION BY bp.BOOKSET_ID,bp.BOK_DETAIL_ID,bp.HAPPEN_DATE ORDER BY bp.BOOK_SUMMARY_ORDER desc) as riw from BOK_STAT_DET_POSIITON bp where bp.FINPROD_TYPE='F01' --债券 and bp.INV_AIM !='AC' and bp.BOOK_DATE <=to_date(#{sysDate,jdbcType=VARCHAR},'yyyy-MM-dd') and bp.HAPPEN_DATE <=to_date(#{sysDate,jdbcType=VARCHAR},'yyyy-MM-dd') and bp.POS_AMT!=0
and bp.BOOKSET_ID in
#{item}
) temp where temp.riw=1 )TL LEFT JOIN ( SELECT td.FINPROD_ID, td.FINPROD_TYPE, td.INV_AIM, tb.INV_AIM as C_INV_AIM, ba.BOOKSET_ID FROM TRD_FIN_PRODUCT_BARTER tb inner join TRD_PRODUCT_DEAL td on tb.TRADE_ID=td.TRADE_ID and tb.FINPROD_ID=td.FINPROD_ID and tb.FINPROD_TYPE=td.FINPROD_TYPE inner join BOK_DEAL_ACCOUNTING ba on tb.TRADE_ID=ba.BUSI_NO --入账信息表.业务表=交易表 where tb.FINPROD_TYPE='F01' --债券 and td.TRADE_DATE=to_date(#{sysDate,jdbcType=VARCHAR},'yyyy-MM-dd') --平台日期日 ) JY ON TL.BOOKSET_ID=JY.BOOKSET_ID AND TL.BUSI_ID=JY.FINPROD_ID AND TL.FINPROD_TYPE=JY.FINPROD_TYPE AND TL.INV_AIM=JY.INV_AIM ) tc group by tc.happenDate,tc.booksetDate,tc.bookDate,tc.booksetId,tc.bokDetailId,tc.invAim

